### Module 1: Virtual File System (VFS) Sandbox

This module maps virtual paths to isolated physical directories on disk. It intercepts and blocks directory traversal exploits (e.g., `../../etc/passwd` or null-byte injections) by parsing, resolving, and validating paths prior to operating system invocation.

```csharp
namespace EnterpriseSftp.Core.Vfs
{
    using System;
    using System.IO;
    using System.Runtime.InteropServices;
    using System.Security;
    using System.Threading;
    using System.Threading.Tasks;

    public interface IVirtualFileSystem
    {
        string VirtualRoot { get; }
        Task<Stream> OpenFileAsync(string virtualPath, FileMode mode, FileAccess access, FileShare share, CancellationToken cancellationToken = default);
        Task CreateDirectoryAsync(string virtualPath, CancellationToken cancellationToken = default);
        Task DeleteFileAsync(string virtualPath, CancellationToken cancellationToken = default);
        Task DeleteDirectoryAsync(string virtualPath, bool recursive, CancellationToken cancellationToken = default);
        Task<bool> FileExistsAsync(string virtualPath, CancellationToken cancellationToken = default);
        Task<bool> DirectoryExistsAsync(string virtualPath, CancellationToken cancellationToken = default);
        Task<FileAttributesData> GetAttributesAsync(string virtualPath, CancellationToken cancellationToken = default);
    }

    public record FileAttributesData(long Size, bool IsDirectory, DateTime LastAccessTime, DateTime LastWriteTime);

    public class VirtualFileSystem : IVirtualFileSystem
    {
        private readonly string _physicalRoot;
        private readonly StringComparison _comparisonType;

        public string VirtualRoot => "/";

        public VirtualFileSystem(string physicalRootPath)
        {
            if (string.IsNullOrWhiteSpace(physicalRootPath))
                throw new ArgumentNullException(nameof(physicalRootPath));

            _physicalRoot = Path.GetFullPath(physicalRootPath);
            _comparisonType = RuntimeInformation.IsOSPlatform(OSPlatform.Windows) 
                ? StringComparison.OrdinalIgnoreCase 
                : StringComparison.Ordinal;

            if (!Directory.Exists(_physicalRoot))
            {
                Directory.CreateDirectory(_physicalRoot);
            }
        }

        public string ResolvePhysicalPath(string virtualPath)
        {
            if (string.IsNullOrEmpty(virtualPath)) 
                virtualPath = "/";

            // 1. Unify directory separators to forward slashes
            string normalized = virtualPath.Replace('\\', '/');

            // 2. Tokenize and clean relative path segments (preventing '..' injection)
            string[] segments = normalized.Split('/', StringSplitOptions.RemoveEmptyEntries);
            var safeStack = new System.Collections.Generic.Stack<string>();

            foreach (var segment in segments)
            {
                if (segment == "." || string.IsNullOrWhiteSpace(segment)) 
                    continue;

                if (segment == "..")
                {
                    if (safeStack.Count > 0) 
                        safeStack.Pop();
                    continue;
                }

                // Guard against null-byte injection vulnerabilities
                if (segment.Contains('\0'))
                {
                    throw new SecurityException("Null-byte sequence detected within path execution.");
                }

                safeStack.Push(segment);
            }

            // 3. Reconstruct safe relative path
            string cleanVirtual = string.Join(Path.DirectorySeparatorChar.ToString(), safeStack.ToArray());

            // 4. Combine with Physical Root and fully resolve via OS canonicalization
            string combinedPath = Path.Combine(_physicalRoot, cleanVirtual);
            string physicalPath = Path.GetFullPath(combinedPath);

            // 5. Strict Sandboxed/Chroot Jail Validation Check
            if (!physicalPath.StartsWith(_physicalRoot, _comparisonType))
            {
                throw new SecurityException($"Directory traversal attempt blocked. Path '{virtualPath}' resolved outside sandbox root.");
            }

            return physicalPath;
        }

        public Task<Stream> OpenFileAsync(string virtualPath, FileMode mode, FileAccess access, FileShare share, CancellationToken cancellationToken = default)
        {
            string path = ResolvePhysicalPath(virtualPath);

            // Prevent creating files in directories that do not exist
            string? parentDir = Path.GetDirectoryName(path);
            if (parentDir != null && !Directory.Exists(parentDir))
            {
                Directory.CreateDirectory(parentDir);
            }

            var stream = new FileStream(path, mode, access, share, bufferSize: 4096, useAsync: true);
            return Task.FromResult<Stream>(stream);
        }

        public Task CreateDirectoryAsync(string virtualPath, CancellationToken cancellationToken = default)
        {
            string path = ResolvePhysicalPath(virtualPath);
            Directory.CreateDirectory(path);
            return Task.CompletedTask;
        }

        public Task DeleteFileAsync(string virtualPath, CancellationToken cancellationToken = default)
        {
            string path = ResolvePhysicalPath(virtualPath);
            if (!File.Exists(path))
                throw new FileNotFoundException("Target file not found for deletion.", path);

            File.Delete(path);
            return Task.CompletedTask;
        }

        public Task DeleteDirectoryAsync(string virtualPath, bool recursive, CancellationToken cancellationToken = default)
        {
            string path = ResolvePhysicalPath(virtualPath);
            if (!Directory.Exists(path))
                throw new DirectoryNotFoundException($"Target directory '{virtualPath}' not found.");

            Directory.Delete(path, recursive);
            return Task.CompletedTask;
        }

        public Task<bool> FileExistsAsync(string virtualPath, CancellationToken cancellationToken = default)
        {
            string path = ResolvePhysicalPath(virtualPath);
            return Task.FromResult(File.Exists(path));
        }

        public Task<bool> DirectoryExistsAsync(string virtualPath, CancellationToken cancellationToken = default)
        {
            string path = ResolvePhysicalPath(virtualPath);
            return Task.FromResult(Directory.Exists(path));
        }

        public Task<FileAttributesData> GetAttributesAsync(string virtualPath, CancellationToken cancellationToken = default)
        {
            string path = ResolvePhysicalPath(virtualPath);
            var info = new FileInfo(path);

            if (Directory.Exists(path))
            {
                var dirInfo = new DirectoryInfo(path);
                return Task.FromResult(new FileAttributesData(0, true, dirInfo.LastAccessTime, dirInfo.LastWriteTime));
            }

            if (!info.Exists)
                throw new FileNotFoundException($"The requested path '{virtualPath}' does not resolve to an active node.");

            return Task.FromResult(new FileAttributesData(info.Length, false, info.LastAccessTime, info.LastWriteTime));
        }
    }
}
```

