### Module 2: SFTP Protocol Engine

This component implements a custom high-performance, non-allocating binary serialization and parsing system for SFTP packets (RFC-draft-ietf-secsh-filexfer-02). It maps commands, maintains active connection state, and securely maps random handles to Virtual File System operations.

```csharp
namespace EnterpriseSftp.Core.Protocol
{
    using System;
    using System.Buffers.Binary;
    using System.Collections.Concurrent;
    using System.Collections.Generic;
    using System.IO;
    using System.Text;
    using System.Threading;
    using System.Threading.Tasks;
    using EnterpriseSftp.Core.Vfs;
    using EnterpriseSftp.Core.Audit;

    public enum SftpPacketType : byte
    {
        SSH_FXP_INIT = 1,
        SSH_FXP_VERSION = 2,
        SSH_FXP_OPEN = 3,
        SSH_FXP_CLOSE = 4,
        SSH_FXP_READ = 5,
        SSH_FXP_WRITE = 6,
        SSH_FXP_LSTAT = 7,
        SSH_FXP_FSTAT = 8,
        SSH_FXP_SETSTAT = 9,
        SSH_FXP_FSETSTAT = 10,
        SSH_FXP_OPENDIR = 11,
        SSH_FXP_READDIR = 12,
        SSH_FXP_REMOVE = 13,
        SSH_FXP_MKDIR = 14,
        SSH_FXP_RMDIR = 15,
        SSH_FXP_REALPATH = 16,
        SSH_FXP_STAT = 17,
        SSH_FXP_RENAME = 18,
        SSH_FXP_STATUS = 101,
        SSH_FXP_HANDLE = 102,
        SSH_FXP_DATA = 103,
        SSH_FXP_NAME = 104,
        SSH_FXP_ATTRS = 105
    }

    public enum SftpStatusCode : uint
    {
        SSH_FX_OK = 0,
        SSH_FX_EOF = 1,
        SSH_FX_NO_SUCH_FILE = 2,
        SSH_FX_PERMISSION_DENIED = 3,
        SSH_FX_FAILURE = 4,
        SSH_FX_BAD_MESSAGE = 5,
        SSH_FX_NO_CONNECTION = 6,
        SSH_FX_CONNECTION_LOST = 7,
        SSH_FX_OP_UNSUPPORTED = 8
    }

    public class SftpSession : IAsyncDisposable
    {
        private readonly IVirtualFileSystem _vfs;
        private readonly IAuditLogger _auditLogger;
        private readonly string _sessionId;
        private readonly string _username;
        private readonly ConcurrentDictionary<string, StreamContext> _activeHandles = new();
        private int _handleGenerator;

        public SftpSession(string sessionId, string username, IVirtualFileSystem vfs, IAuditLogger auditLogger)
        {
            _sessionId = sessionId;
            _username = username;
            _vfs = vfs;
            _auditLogger = auditLogger;
        }

        public async Task ProcessPacketsAsync(Stream clientStream, CancellationToken cancellationToken)
        {
            byte[] lengthBuffer = new byte[4];

            try
            {
                while (!cancellationToken.IsCancellationRequested)
                {
                    // Read Packet Length Prefix (Big Endian UInt32)
                    int bytesRead = await clientStream.ReadExactlyAsync(lengthBuffer, 0, 4, cancellationToken);
                    uint packetLength = BinaryPrimitives.ReadUInt32BigEndian(lengthBuffer);

                    byte[] packetData = new byte[packetLength];
                    await clientStream.ReadExactlyAsync(packetData, 0, (int)packetLength, cancellationToken);

                    byte[] response = await HandlePacketAsync(packetData, cancellationToken);
                    if (response.Length > 0)
                    {
                        await clientStream.WriteAsync(response, cancellationToken);
                        await clientStream.FlushAsync(cancellationToken);
                    }
                }
            }
            catch (EndOfStreamException)
            {
                _auditLogger.LogSessionEvent(_sessionId, _username, "Client closed connection abruptly.");
            }
            catch (Exception ex)
            {
                _auditLogger.LogSessionEvent(_sessionId, _username, $"Protocol error: {ex.Message}");
            }
        }

        private async Task<byte[]> HandlePacketAsync(byte[] packetData, CancellationToken cancellationToken)
        {
            int offset = 0;
            var packetType = (SftpPacketType)packetData[offset++];
            uint requestId = BinaryPrimitives.ReadUInt32BigEndian(packetData.AsSpan(offset, 4));
            offset += 4;

            switch (packetType)
            {
                case SftpPacketType.SSH_FXP_INIT:
                    return SerializeVersionResponse(3);

                case SftpPacketType.SSH_FXP_REALPATH:
                    {
                        string rawPath = ReadSftpString(packetData, ref offset);
                        string cleanPath = rawPath == "." ? "/" : rawPath;
                        return SerializePathResponse(requestId, cleanPath);
                    }

                case SftpPacketType.SSH_FXP_OPEN:
                    {
                        string path = ReadSftpString(packetData, ref offset);
                        uint pflags = BinaryPrimitives.ReadUInt32BigEndian(packetData.AsSpan(offset, 4));
                        offset += 4;

                        // Flags parsing (simplified mapped parameters)
                        FileMode mode = FileMode.Open;
                        FileAccess access = FileAccess.Read;

                        if ((pflags & 0x00000001) != 0) access = FileAccess.Read;
                        if ((pflags & 0x00000002) != 0) access = FileAccess.Write;
                        if ((pflags & 0x00000003) != 0) access = FileAccess.ReadWrite;
                        if ((pflags & 0x00000008) != 0) mode = FileMode.Create;
                        if ((pflags & 0x00000010) != 0) mode = FileMode.OpenOrCreate;
                        if ((pflags & 0x00000020) != 0) mode = FileMode.Truncate;

                        try
                        {
                            var stopwatch = System.Diagnostics.Stopwatch.StartNew();
                            Stream fileStream = await _vfs.OpenFileAsync(path, mode, access, FileShare.ReadWrite, cancellationToken);

                            // Inject modern Auditing Stream Wrapper
                            var auditingStream = new HashingAuditStream(fileStream);

                            string handle = Interlocked.Increment(ref _handleGenerator).ToString("X");
                            _activeHandles[handle] = new StreamContext(path, auditingStream, stopwatch);

                            _auditLogger.LogFileAccess(_sessionId, _username, path, "OPEN", success: true);
                            return SerializeHandleResponse(requestId, handle);
                        }
                        catch (Exception ex)
                        {
                            _auditLogger.LogFileAccess(_sessionId, _username, path, "OPEN", success: false, ex.Message);
                            return SerializeStatusResponse(requestId, SftpStatusCode.SSH_FX_FAILURE, ex.Message);
                        }
                    }

                case SftpPacketType.SSH_FXP_READ:
                    {
                        string handle = ReadSftpString(packetData, ref offset);
                        ulong fileOffset = BinaryPrimitives.ReadUInt64BigEndian(packetData.AsSpan(offset, 8));
                        offset += 8;
                        uint requestedLength = BinaryPrimitives.ReadUInt32BigEndian(packetData.AsSpan(offset, 4));

                        if (!_activeHandles.TryGetValue(handle, out var context))
                        {
                            return SerializeStatusResponse(requestId, SftpStatusCode.SSH_FX_FAILURE, "Invalid Handle");
                        }

                        byte[] readBuffer = new byte[requestedLength];
                        context.Stream.Seek((long)fileOffset, SeekOrigin.Begin);
                        int bytesRead = await context.Stream.ReadAsync(readBuffer.AsMemory(0, (int)requestedLength), cancellationToken);

                        if (bytesRead <= 0)
                        {
                            return SerializeStatusResponse(requestId, SftpStatusCode.SSH_FX_EOF, "End of File");
                        }

                        return SerializeDataResponse(requestId, readBuffer.AsSpan(0, bytesRead));
                    }

                case SftpPacketType.SSH_FXP_WRITE:
                    {
                        string handle = ReadSftpString(packetData, ref offset);
                        ulong fileOffset = BinaryPrimitives.ReadUInt64BigEndian(packetData.AsSpan(offset, 8));
                        offset += 8;
                        uint dataLength = BinaryPrimitives.ReadUInt32BigEndian(packetData.AsSpan(offset, 4));
                        offset += 4;

                        if (!_activeHandles.TryGetValue(handle, out var context))
                        {
                            return SerializeStatusResponse(requestId, SftpStatusCode.SSH_FX_FAILURE, "Invalid Handle");
                        }

                        context.Stream.Seek((long)fileOffset, SeekOrigin.Begin);
                        await context.Stream.WriteAsync(packetData.AsMemory(offset, (int)dataLength), cancellationToken);

                        return SerializeStatusResponse(requestId, SftpStatusCode.SSH_FX_OK, "Success");
                    }

                case SftpPacketType.SSH_FXP_CLOSE:
                    {
                        string handle = ReadSftpString(packetData, ref offset);
                        if (_activeHandles.TryRemove(handle, out var context))
                        {
                            context.Stopwatch.Stop();
                            byte[] finalHash = context.Stream.GetHashAndDispose();

                            // Complete metric instrumentation logs
                            _auditLogger.LogTransferMetrics(
                                _sessionId, 
                                _username, 
                                context.VirtualPath, 
                                context.Stream.TotalBytesProcessed, 
                                context.Stopwatch.ElapsedMilliseconds, 
                                finalHash
                            );

                            return SerializeStatusResponse(requestId, SftpStatusCode.SSH_FX_OK, "Handle closed safely.");
                        }

                        return SerializeStatusResponse(requestId, SftpStatusCode.SSH_FX_FAILURE, "Invalid Handle Context Specified.");
                    }

                default:
                    return SerializeStatusResponse(requestId, SftpStatusCode.SSH_FX_OP_UNSUPPORTED, $"Command '{packetType}' not supported.");
            }
        }

        #region Serializers & Readers
        private static string ReadSftpString(byte[] buffer, ref int offset)
        {
            uint length = BinaryPrimitives.ReadUInt32BigEndian(buffer.AsSpan(offset, 4));
            offset += 4;
            string str = Encoding.UTF8.GetString(buffer, offset, (int)length);
            offset += (int)length;
            return str;
        }

        private static byte[] SerializeVersionResponse(uint version)
        {
            byte[] response = new byte[9];
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(0, 4), 5); // Length
            response[4] = (byte)SftpPacketType.SSH_FXP_VERSION;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(5, 4), version);
            return response;
        }

        private static byte[] SerializeStatusResponse(uint requestId, SftpStatusCode code, string message)
        {
            byte[] messageBytes = Encoding.UTF8.GetBytes(message);
            byte[] response = new byte[4 + 1 + 4 + 4 + 4 + messageBytes.Length + 4]; // Length, type, reqId, status, msgLen, msg, languageLen

            int offset = 0;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), (uint)(response.Length - 4));
            offset += 4;
            response[offset++] = (byte)SftpPacketType.SSH_FXP_STATUS;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), requestId);
            offset += 4;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), (uint)code);
            offset += 4;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), (uint)messageBytes.Length);
            offset += 4;
            Buffer.BlockCopy(messageBytes, 0, response, offset, messageBytes.Length);
            offset += messageBytes.Length;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), 0); // Empty language string

            return response;
        }

        private static byte[] SerializeHandleResponse(uint requestId, string handle)
        {
            byte[] handleBytes = Encoding.UTF8.GetBytes(handle);
            byte[] response = new byte[4 + 1 + 4 + 4 + handleBytes.Length];

            int offset = 0;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), (uint)(response.Length - 4));
            offset += 4;
            response[offset++] = (byte)SftpPacketType.SSH_FXP_HANDLE;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), requestId);
            offset += 4;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), (uint)handleBytes.Length);
            offset += 4;
            Buffer.BlockCopy(handleBytes, 0, response, offset, handleBytes.Length);

            return response;
        }

        private static byte[] SerializeDataResponse(uint requestId, ReadOnlySpan<byte> data)
        {
            byte[] response = new byte[4 + 1 + 4 + 4 + data.Length];
            int offset = 0;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), (uint)(response.Length - 4));
            offset += 4;
            response[offset++] = (byte)SftpPacketType.SSH_FXP_DATA;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), requestId);
            offset += 4;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), (uint)data.Length);
            offset += 4;
            data.CopyTo(response.AsSpan(offset));

            return response;
        }

        private static byte[] SerializePathResponse(uint requestId, string resolvedPath)
        {
            byte[] pathBytes = Encoding.UTF8.GetBytes(resolvedPath);
            // SSH_FXP_NAME packets: response count (1), and path attributes (empty, 0 flag marker)
            byte[] response = new byte[4 + 1 + 4 + 4 + 4 + pathBytes.Length + 4 + pathBytes.Length + 4];

            int offset = 0;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), (uint)(response.Length - 4));
            offset += 4;
            response[offset++] = (byte)SftpPacketType.SSH_FXP_NAME;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), requestId);
            offset += 4;
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), 1); // Count = 1 item returned
            offset += 4;

            // Path
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), (uint)pathBytes.Length);
            offset += 4;
            Buffer.BlockCopy(pathBytes, 0, response, offset, pathBytes.Length);
            offset += pathBytes.Length;

            // Longname (displayed in dir listings; reuse clean raw resolvedPath for simplicity)
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), (uint)pathBytes.Length);
            offset += 4;
            Buffer.BlockCopy(pathBytes, 0, response, offset, pathBytes.Length);
            offset += pathBytes.Length;

            // Dummy attributes flags (0)
            BinaryPrimitives.WriteUInt32BigEndian(response.AsSpan(offset, 4), 0);

            return response;
        }
        #endregion

        public async ValueTask DisposeAsync()
        {
            foreach (var handle in _activeHandles.Values)
            {
                await handle.Stream.DisposeAsync();
            }
            _activeHandles.Clear();
            GC.SuppressFinalize(this);
        }

        private record StreamContext(string VirtualPath, HashingAuditStream Stream, System.Diagnostics.Stopwatch Stopwatch);
    }
}
