### Module 3: SSH Transport Layer Security

This component implements key elements of the SSH Transport Layer Protocol (RFC 4253), showing how to handle the handshaking, key exchange (KEX) negotiation state machine, symmetric key derivation, and cryptographic payload framing.

```csharp
namespace EnterpriseSftp.Core.Security
{
    using System;
    using System.Security.Cryptography;
    using System.Text;

    public class SshCryptoContext
    {
        public bool EncryptedTransmissionEnabled { get; private set; }
        private byte[]? _encryptionKey;
        private byte[]? _integrityMacKey;

        private AesGcm? _aesGcmEncryptor;
        private HMACSHA256? _hmacSha256;

        public void InitializeKeys(byte[] sharedSecretK, byte[] exchangeHashH, byte[] sessionId)
        {
            // SSH Key Derivation Function (RFC 4253 Section 7.2)
            // K_encrypt = HASH(SharedSecret || HashH || 'C' || SessionId)
            // K_mac     = HASH(SharedSecret || HashH || 'E' || SessionId)

            _encryptionKey = DeriveSshKey(sharedSecretK, exchangeHashH, 'C', sessionId, 32); // AES-256 (32 Bytes)
            _integrityMacKey = DeriveSshKey(sharedSecretK, exchangeHashH, 'E', sessionId, 32); // HMAC-SHA2-256 (32 Bytes)

            _aesGcmEncryptor = new AesGcm(_encryptionKey, tagSizeInBytes: 16);
            _hmacSha256 = new HMACSHA256(_integrityMacKey);

            EncryptedTransmissionEnabled = true;
        }

        private static byte[] DeriveSshKey(byte[] k, byte[] h, char keyChar, byte[] sessionId, int requiredLength)
        {
            using var ms = new MemoryStream();
            ms.Write(k);
            ms.Write(h);
            ms.Write(new[] { (byte)keyChar });
            ms.Write(sessionId);

            byte[] input = ms.ToArray();
            byte[] digest = SHA256.HashData(input);

            if (digest.Length >= requiredLength)
            {
                return digest.AsSpan(0, requiredLength).ToArray();
            }

            // If key size is larger than hashing block, run iterative chaining: HASH(K || H || PreviousDigest)
            var expandedKey = new byte[requiredLength];
            Buffer.BlockCopy(digest, 0, expandedKey, 0, digest.Length);
            int currentLength = digest.Length;

            while (currentLength < requiredLength)
            {
                using var chainMs = new MemoryStream();
                chainMs.Write(k);
                chainMs.Write(h);
                chainMs.Write(digest);
                digest = SHA256.HashData(chainMs.ToArray());

                int copySize = Math.Min(digest.Length, requiredLength - currentLength);
                Buffer.BlockCopy(digest, 0, expandedKey, currentLength, copySize);
                currentLength += copySize;
            }

            return expandedKey;
        }

        public byte[] EncryptPayload(ReadOnlySpan<byte> payload)
        {
            if (!EncryptedTransmissionEnabled || _aesGcmEncryptor == null)
            {
                return payload.ToArray(); // Unencrypted fallback (during key exchange)
            }

            // Generate RFC-compliant random 12-byte initialization vector (IV)
            byte[] nonce = new byte[12];
            RandomNumberGenerator.Fill(nonce);

            byte[] cipherText = new byte[payload.Length];
            byte[] tag = new byte[16];

            _aesGcmEncryptor.Encrypt(nonce, payload, cipherText, tag);

            // Construct Binary Frame
            byte[] packet = new byte[12 + cipherText.Length + 16];
            Buffer.BlockCopy(nonce, 0, packet, 0, 12);
            Buffer.BlockCopy(cipherText, 0, packet, 12, cipherText.Length);
            Buffer.BlockCopy(tag, 0, packet, 12 + cipherText.Length, 16);

            return packet;
        }

        public byte[] DecryptPayload(ReadOnlySpan<byte> encryptedFrame)
        {
            if (!EncryptedTransmissionEnabled || _aesGcmEncryptor == null)
            {
                return encryptedFrame.ToArray();
            }

            if (encryptedFrame.Length < 28) // IV (12) + Tag (16)
                throw new CryptographicException("Corrupted SSH security frame structure.");

            ReadOnlySpan<byte> nonce = encryptedFrame.Slice(0, 12);
            ReadOnlySpan<byte> cipherText = encryptedFrame.Slice(12, encryptedFrame.Length - 28);
            ReadOnlySpan<byte> tag = encryptedFrame.Slice(encryptedFrame.Length - 16, 16);

            byte[] decryptedBytes = new byte[cipherText.Length];
            _aesGcmEncryptor.Decrypt(nonce, cipherText, tag, decryptedBytes);

            return decryptedBytes;
        }
    }

    public class SshKeyExchangeEngine
    {
        private readonly ECDiffieHellmanCng _ecdh;
        public byte[] PublicKey { get; }

        public SshKeyExchangeEngine()
        {
            _ecdh = new ECDiffieHellmanCng(256)
            {
                KeyDerivationFunction = ECDiffieHellmanKeyDerivationFunction.Hash,
                HashAlgorithm = CngAlgorithm.Sha256
            };
            PublicKey = _ecdh.PublicKey.ToByteArray();
        }

        public byte[] ComputeSharedSecret(byte[] clientPublicKey)
        {
            using var externalPublicKey = CngKey.Import(clientPublicKey, CngKeyBlobFormat.EccPublicBlob);
            return _ecdh.DeriveKeyMaterial(externalPublicKey);
        }
    }
}
