### Module 4: Audit Logging & Metrics Subsystem

This module generates clean, structured JSON event logging, performs real-time data calculations, calculates transfer speeds, and tracks the exact SHA256 integrity hash of a file as it streams over the wire.

```csharp
namespace EnterpriseSftp.Core.Audit
{
    using System;
    using System.IO;
    using System.Security.Cryptography;
    using System.Text.Json;
    using Microsoft.Extensions.Logging;

    public interface IAuditLogger
    {
        void LogSessionEvent(string sessionId, string username, string details);
        void LogFileAccess(string sessionId, string username, string path, string operation, bool success, string? errorDetail = null);
        void LogTransferMetrics(string sessionId, string username, string path, long totalBytes, long durationMs, byte[] sha256Hash);
    }

    public class AuditLogger : IAuditLogger
    {
        private readonly ILogger<AuditLogger> _logger;

        public AuditLogger(ILogger<AuditLogger> logger)
        {
            _logger = logger;
        }

        public void LogSessionEvent(string sessionId, string username, string details)
        {
            var logPayload = new
            {
                Timestamp = DateTime.UtcNow,
                Type = "SessionActivity",
                SessionId = sessionId,
                User = username,
                Details = details
            };
            _logger.LogInformation("{AuditLogJson}", JsonSerializer.Serialize(logPayload));
        }

        public void LogFileAccess(string sessionId, string username, string path, string operation, bool success, string? errorDetail = null)
        {
            var logPayload = new
            {
                Timestamp = DateTime.UtcNow,
                Type = "FileAccessEvent",
                SessionId = sessionId,
                User = username,
                Path = path,
                Operation = operation,
                Success = success,
                ErrorDetail = errorDetail
            };

            if (success)
            {
                _logger.LogInformation("{AuditLogJson}", JsonSerializer.Serialize(logPayload));
            }
            else
            {
                _logger.LogWarning("{AuditLogJson}", JsonSerializer.Serialize(logPayload));
            }
        }

        public void LogTransferMetrics(string sessionId, string username, string path, long totalBytes, long durationMs, byte[] sha256Hash)
        {
            double seconds = durationMs / 1000.0;
            double transferRateMb = seconds > 0 ? (totalBytes / (1024.0 * 1024.0)) / seconds : 0.0;
            string sha256String = Convert.ToHexString(sha256Hash);

            var logPayload = new
            {
                Timestamp = DateTime.UtcNow,
                Type = "FileTransferMetric",
                SessionId = sessionId,
                User = username,
                Path = path,
                TotalBytes = totalBytes,
                DurationMilliseconds = durationMs,
                TransferRateMBs = Math.Round(transferRateMb, 2),
                SHA256IntegrityHash = sha256String
            };

            _logger.LogInformation("{AuditLogJson}", JsonSerializer.Serialize(logPayload));
        }
    }

    /// <summary>
    /// Wrapper stream class that calculates cryptographic SHA256 digests and measures exact 
    /// throughput size incrementally without copying memory buffers.
    /// </summary>
    public class HashingAuditStream : Stream
    {
        private readonly Stream _baseStream;
        private readonly IncrementalHash _shaHasher;
        public long TotalBytesProcessed { get; private set; }

        public HashingAuditStream(Stream baseStream)
        {
            _baseStream = baseStream ?? throw new ArgumentNullException(nameof(baseStream));
            _shaHasher = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
        }

        public override bool CanRead => _baseStream.CanRead;
        public override bool CanSeek => _baseStream.CanSeek;
        public override bool CanWrite => _baseStream.CanWrite;
        public override long Length => _baseStream.Length;

        public override long Position
        {
            get => _baseStream.Position;
            set => _baseStream.Position = value;
        }

        public override void Flush() => _baseStream.Flush();

        public override int Read(byte[] buffer, int offset, int count)
        {
            int read = _baseStream.Read(buffer, offset, count);
            if (read > 0)
            {
                _shaHasher.AppendData(buffer, offset, read);
                TotalBytesProcessed += read;
            }
            return read;
        }

        public override async ValueTask<int> ReadAsync(Memory<byte> buffer, CancellationToken cancellationToken = default)
        {
            int read = await _baseStream.ReadAsync(buffer, cancellationToken);
            if (read > 0)
            {
                _shaHasher.AppendData(buffer.Span[..read]);
                TotalBytesProcessed += read;
            }
            return read;
        }

        public override void Write(byte[] buffer, int offset, int count)
        {
            _baseStream.Write(buffer, offset, count);
            _shaHasher.AppendData(buffer, offset, count);
            TotalBytesProcessed += count;
        }

        public override async ValueTask WriteAsync(ReadOnlyMemory<byte> buffer, CancellationToken cancellationToken = default)
        {
            await _baseStream.WriteAsync(buffer, cancellationToken);
            _shaHasher.AppendData(buffer.Span);
            TotalBytesProcessed += buffer.Length;
        }

        public override long Seek(long offset, SeekOrigin origin) => _baseStream.Seek(offset, origin);
        public override void SetLength(long value) => _baseStream.SetLength(value);

        public byte[] GetHashAndDispose()
        {
            byte[] hash = _shaHasher.GetHashAndReset();
            _shaHasher.Dispose();
            return hash;
        }

        protected override void Dispose(bool disposing)
        {
            if (disposing)
            {
                _baseStream.Dispose();
            }
            base.Dispose(disposing);
        }

        public override async ValueTask DisposeAsync()
        {
            await _baseStream.DisposeAsync();
            await base.DisposeAsync();
        }
    }
}
