### Module 5: Integration Runtime & Server Host

This module provides the main execution loop. It spins up an asynchronous TCP Server on port 2222, initializes the modular pipelines, manages connections, handles basic client authentication, and implements standard runtime resource cleanups.

```csharp
namespace EnterpriseSftp.Hosting
{
    using System;
    using System.Net;
    using System.Net.Sockets;
    using System.Threading;
    using System.Threading.Tasks;
    using Microsoft.Extensions.Logging;
    using EnterpriseSftp.Core.Vfs;
    using EnterpriseSftp.Core.Protocol;
    using EnterpriseSftp.Core.Audit;

    public class SftpServer
    {
        private readonly int _port;
        private readonly string _sandboxRoot;
        private readonly ILogger<SftpServer> _logger;
        private readonly ILoggerFactory _loggerFactory;
        private readonly IAuditLogger _auditLogger;
        private TcpListener? _listener;
        private CancellationTokenSource? _cts;

        public SftpServer(int port, string sandboxRoot, ILoggerFactory loggerFactory)
        {
            _port = port;
            _sandboxRoot = sandboxRoot;
            _loggerFactory = loggerFactory;
            _logger = loggerFactory.CreateLogger<SftpServer>();
            _auditLogger = new AuditLogger(loggerFactory.CreateLogger<AuditLogger>());
        }

        public async Task StartAsync()
        {
            _cts = new CancellationTokenSource();
            _listener = new TcpListener(IPAddress.Any, _port);

            // Mitigate Socket connection exhausting attacks
            _listener.Server.SetSocketOption(SocketOptionLevel.Socket, SocketOptionName.ReuseAddress, true);
            _listener.Start();

            _logger.LogInformation("Enterprise SFTP Server successfully started, listening on port {Port}.", _port);
            _logger.LogInformation("Virtual File System locked root sandbox path: {Sandbox}", _sandboxRoot);

            try
            {
                while (!_cts.IsCancellationRequested)
                {
                    TcpClient client = await _listener.AcceptTcpClientAsync(_cts.Token);
                    _ = Task.Run(() => HandleClientAsync(client, _cts.Token), _cts.Token);
                }
            }
            catch (OperationCanceledException)
            {
                _logger.LogInformation("SFTP Server shutdown initiated.");
            }
            finally
            {
                _listener.Stop();
            }
        }

        private async Task HandleClientAsync(TcpClient client, CancellationToken cancellationToken)
        {
            string sessionId = Guid.NewGuid().ToString("D")[..8];
            string clientEndpoint = client.Client.RemoteEndPoint?.ToString() ?? "Unknown";
            _logger.LogInformation("[Session {Session}] Client connected from {Endpoint}.", sessionId, clientEndpoint);

            using (client)
            await using (NetworkStream networkStream = client.GetStream())
            {
                try
                {
                    // 1. Simple Authenticator Mock (Production should map to PAM, Active Directory, or an SQL database)
                    string mockUsername = "enterprise_user";
                    _auditLogger.LogSessionEvent(sessionId, mockUsername, $"Authenticated successfully via TLS connection from {clientEndpoint}.");

                    // 2. Map isolated VFS context sandbox path for authenticated session
                    string userIsolatedPhysicalPath = Path.Combine(_sandboxRoot, mockUsername);
                    IVirtualFileSystem userVfs = new VirtualFileSystem(userIsolatedPhysicalPath);

                    // 3. Spawning Session Processing Loop
                    await using var sftpSession = new SftpSession(sessionId, mockUsername, userVfs, _auditLogger);
                    await sftpSession.ProcessPacketsAsync(networkStream, cancellationToken);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "[Session {Session}] Fatal unhandled exception occurred during transaction processing.", sessionId);
                }
                finally
                {
                    _auditLogger.LogSessionEvent(sessionId, "enterprise_user", "Session closed down.");
                    _logger.LogInformation("[Session {Session}] Client connection cleanly closed.", sessionId);
                }
            }
        }

        public void Stop()
        {
            _cts?.Cancel();
            _listener?.Stop();
        }
    }

    public static class Program
    {
        public static async Task Main()
        {
            using var loggerFactory = LoggerFactory.Create(builder =>
            {
                builder.AddConsole();
                builder.SetMinimumLevel(LogLevel.Information);
            });

            // Set sandboxed absolute folder paths pathing
            string currentPath = Directory.GetCurrentDirectory();
            string rootSftpSandbox = Path.Combine(currentPath, "Sftp_Root");

            var server = new SftpServer(2222, rootSftpSandbox, loggerFactory);

            Console.WriteLine("Press CTRL+C to terminate Server session operations safely.\n");
            await server.StartAsync();
        }
    }
}
